NOTICE = "Adapted DINOv3 inference components from Mattia Angeli's public notebook:\nhttps://www.kaggle.com/code/mattiaangeli/bend-the-knee-to-dinov3-ensembled\nThe original notebook is released under Apache License 2.0.\nPreprocessing, architecture classes, and normalization are adapted from its\nstandalone DINOv3 member. Changes are recorded in readme.txt and inference.py.\nCheckpoint source: https://www.kaggle.com/datasets/mattiaangeli/knee-mri-fold-weights\nUnderlying backbone: Meta DINOv3, https://github.com/facebookresearch/dinov3\nBackbone license: https://github.com/facebookresearch/dinov3/blob/main/LICENSE.md\n\nCoAtNet checkpoint: Johnathan Wagner / Dread Development, CC0.\nhttps://www.kaggle.com/datasets/dreaddevelopment/raptor-knee-maxspan\n"

def main():
    started = time.time()
    out = Path('/kaggle/working')
    (out/'LICENSE-APACHE-2.0.txt').write_text(LICENSE_APACHE)
    (out/'LICENSE-DINOv3.md').write_text(LICENSE_DINO)
    (out/'NOTICE.txt').write_text(NOTICE)
    # CoAtNet runs before DINO installs its pinned timm wheel.
    for name, code in [('model12',MODEL12_CODE),('model13',MODEL13_CODE)]:
        script = out/f'{name}_component.py'
        script.write_text(code)
        subprocess.run([sys.executable,str(script)],check=True)
        (out/'submission.csv').replace(out/f'{name}_predictions.csv')
    uid = 'StudyInstanceUID'
    a = pd.read_csv(out/'model12_predictions.csv').set_index(uid)
    b = pd.read_csv(out/'model13_predictions.csv').set_index(uid)
    assert a.index.is_unique and b.index.is_unique and set(a.index)==set(b.index)
    assert list(a.columns)==list(b.columns)
    b = b.loc[a.index]
    x,y = a.to_numpy(),b.to_numpy()
    assert np.isfinite(x).all() and np.isfinite(y).all()
    if len(a)>1:
        pred = .5*(rankdata(x,axis=0)-1)/(len(a)-1) + .5*(rankdata(y,axis=0)-1)/(len(a)-1)
    else:
        pred = .5*x+.5*y
    assert np.isfinite(pred).all() and ((pred>=0)&(pred<=1)).all()
    frame = pd.DataFrame(pred,index=a.index,columns=a.columns)
    frame.to_csv(out/'submission.csv')
    runtime={'studies':len(a),'elapsed_seconds':time.time()-started,'blend':'equal ranks: model12, model13'}
    (out/'ensemble_runtime.json').write_text(json.dumps(runtime,indent=2))
    print(json.dumps(runtime),flush=True)


if __name__=='__main__':
    main()
